/** Daftar seri milik satu brand (UUID). */
export function getSeriByBrandId(brandId: string): ProdukKomersialSeri[] {
  return PK_BATCH1_SERI_LIST.filter(s => s.brandId === brandId);
}

/** Lookup satu seri via kategoriSlug + brandId + seriSlug (routing). */
export function getSeriBySlug(brandId: string, seriSlug: string): ProdukKomersialSeri | undefined {
  return PK_BATCH1_SERI_LIST.find(s => s.brandId === brandId && s.slug === seriSlug);
}

/** Lookup seri via UUID. */
export function getSeriByUUID(uuid: string): ProdukKomersialSeri | undefined {
  return PK_BATCH1_SERI_LIST.find(s => s.uuid === uuid);
}
